std::vector<int> slidingWindowMax(const std::vector<int>& nums, int k) {
    std::deque<int> dq; // store indices
    std::vector<int> out;
    if (k <= 0 || nums.empty()) return out;
    for (int i = 0; i < (int)nums.size(); ++i) {
        while (!dq.empty() && dq.front() <= i - k) dq.pop_front();
        while (!dq.empty() && nums[dq.back()] <= nums[i]) dq.pop_back();
        dq.push_back(i);
        if (i >= k - 1) out.push_back(nums[dq.front()]);
    }
    return out;
}

#include <vector>

std::vector<long long> slidingWindowSum(const std::vector<int>& nums, int k) {
    std::vector<long long> out;
    if (k <= 0 || nums.empty()) return out;
    long long cur = 0;
    for (int i = 0; i < (int)nums.size(); ++i) {
        cur += nums[i];
        if (i >= k) cur -= nums[i - k];
        if (i >= k - 1) out.push_back(cur);
    }
    return out;
}

#include <vector>

std::vector<double> movingAverage(const std::vector<int>& nums, int k) {
    std::vector<double> out;
    if (k <= 0 || nums.empty()) return out;
    long long cur = 0;
    for (int i = 0; i < (int)nums.size(); ++i) {
        cur += nums[i];
        if (i >= k) cur -= nums[i - k];
        if (i >= k - 1) out.push_back((double)cur / k);
    }
    return out;
}

